    /**
     * Verify Google Vertex AI credentials with a lightweight location models list call when parent is supplied.
     *
     * @param  array<string, mixed>  $config  Credential and endpoint settings.
     * @return array{success: bool, message?: string, error?: string}
     */
    public function testConnection(array $config): array
    {
        $accessToken = (string) ($config['access_token'] ?? '');
        $baseUrl = rtrim((string) ($config['url'] ?? 'https://aiplatform.googleapis.com'), '/');
        $parent = (string) ($config['parent'] ?? '');
        if ($accessToken === '') return ['success' => false, 'error' => 'No access token provided.'];
        if ($parent === '') return ['success' => true, 'message' => 'Google Vertex AI token is present. Provide a parent such as projects/example/locations/us-central1 to run a live model-list credential check.'];
        try {
            $response = Http::withHeaders(['Authorization' => 'Bearer '.$accessToken, 'Accept' => 'application/json'])->timeout(10)->get($baseUrl.'/v1/'.str_replace('%2F','/',rawurlencode($parent)).'/models', ['pageSize' => 1]);
            if (!$response->successful()) return ['success' => false, 'error' => 'Vertex AI API returned HTTP '.$response->status().'.'];
            return ['success' => true, 'message' => "Connected to Google Vertex AI at {$baseUrl}."];
        } catch (\Throwable $e) { return ['success' => false, 'error' => $e->getMessage()]; }
    }

    public function validationRules(): array { return ['access_token' => 'nullable|string', 'url' => 'nullable|url']; }

