    public function credentialFields(): array { return $this->configSchema(); }
    public function isIntegration(): bool { return true; }

    /**
     * Create a Google Vertex AI tool from the catalog class name.
     *
     * @param  array<string, mixed>  $context  Optional account context.
     */
    public function createTool(string $class, array $context = []): Tool { return new $class($this->resolveService($context)); }

    /**
     * Resolve a service for the default or named account.
     *
     * @param  array<string, mixed>  $context  Tool creation context.
     */
    private function resolveService(array $context = []): GoogleVertexAiService
    {
        $account = $context['account'] ?? null;
        if ($account !== null) {
            $creds = app(CredentialResolver::class);
            return new GoogleVertexAiService(accessToken: $creds->get('google-vertex-ai', 'access_token', '', $account), baseUrl: $creds->get('google-vertex-ai', 'url', 'https://aiplatform.googleapis.com', $account));
        }
        return app(GoogleVertexAiService::class);
    }

    public function luaDocsPath(): ?string { return __DIR__ . '/../lua-docs/google-vertex-ai.md'; }
